{"path":"events.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Events — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f4efe6;--accent:#7a4f3a;--muted:#8b7b72;--card:#fff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#2b2b2b;background:var(--bg);-webkit-font-smoothing:antialiased}
    header{position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.6));backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.05);z-index:40}
    .wrap{max-width:980px;margin:0 auto;padding:24px}
    nav{display:flex;align-items:center;justify-content:space-between;gap:12px}
    .brand{font-weight:700;color:var(--accent)}
    .links{display:flex;gap:14px}
    .links a{color:var(--muted);text-decoration:none;font-weight:600}
    .hero{display:grid;grid-template-columns:1fr;align-items:center;gap:18px;padding:40px 0}
    .panel{background:linear-gradient(180deg,var(--card),var(--glass));padding:22px;border-radius:12px;box-shadow:0 8px 30px rgba(34,20,12,0.06)}
    .hero h1{margin:0;font-size:28px;color:#2f241f}
    .meta{color:var(--muted);font-size:14px}
    .pattern{position:absolute;right:0;top:0;width:320px;height:320px;opacity:0.07;pointer-events:none}
    main{max-width:980px;margin:24px auto;padding:0 24px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:var(--card);padding:18px;border-radius:12px}
    .next{border-left:4px solid var(--accent);padding-left:14px}
    .event-list{display:flex;flex-direction:column;gap:12px}
    .event{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:8px;background:linear-gradient(180deg,rgba(255,255,255,0.96),rgba(255,255,255,0.9));box-shadow:0 6px 18px rgba(0,0,0,0.03)}
    .event .left{display:flex;flex-direction:column}
    .muted{color:var(--muted);font-size:13px}
    .cta{display:inline-block;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none;font-weight:700}
    footer{padding:36px 24px;color:var(--muted);font-size:14px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .6s cubic-bezier(.2,.9,.2,1),transform .6s cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(12,8,6,0.5);display:none;align-items:center;justify-content:center;z-index:80}
    .modal{width:94%;max-width:760px;background:#fff;padding:22px;border-radius:12px}
    .modal header{display:flex;justify-content:space-between;align-items:center}
    .modes{display:flex;gap:8px;margin:12px 0}
    .modes button{padding:8px 10px;border-radius:8px;border:1px solid #eee;background:#faf6f2}
    .breath-dot{width:80px;height:80px;border-radius:50%;margin:18px auto;background:var(--accent);opacity:.95}

    /* small */
    @media (max-width:880px){.grid{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <div class="links">
          <a href="index.html">Gather</a>
          <a href="events.html">Calendar</a>
          <a href="private-sessions.html">Sessions</a>
          <a href="pricing.html">Invest</a>
          <a href="about.html">Origin</a>
          <a href="faq.html">Guide</a>
          <a href="book.html">Reserve</a>
          <a href="contact.html">Connect</a>
        </div>
      </nav>
    </div>
  </header>

  <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
    <defs>
      <linearGradient id="g1" x1="0" x2="1">
        <stop offset="0" stop-color="#b3927c" stop-opacity="0.6"/>
        <stop offset="1" stop-color="#7a4f3a" stop-opacity="0.3"/>
      </linearGradient>
    </defs>
    <rect width="200" height="200" fill="url(#g1)" />
    <g fill="#fff" opacity="0.06">
      <circle cx="30" cy="40" r="26"/>
      <circle cx="90" cy="120" r="40"/>
      <circle cx="160" cy="60" r="30"/>
    </g>
  </svg>

  <main>
    <section class="hero panel reveal" id="intro">
      <h1>Gatherings in sound — practical, focused, and inviting</h1>
      <p class="meta">Join short communal sound practices and deeper multi-hour gatherings. Each event is staged for clarity — breath, body, and a sense of reset.</p>
      <div style="margin-top:12px;display:flex;gap:12px">
        <a class="cta" href="#next-event">See next event</a>
        <button id="tryBtn" class="cta" style="background:#4b2f23">Try it now</button>
        <a href="book.html" class="cta" style="background:#caa089;color:#371814">Reserve a spot</a>
      </div>
    </section>

    <section class="grid" style="margin-top:18px">
      <div>
        <div class="card reveal" id="next-event">
          <h3 style="margin:0 0 6px 0">Next gathering</h3>
          <div id="nextWidget" class="next">
            <div class="muted" id="nextDate">Finding next date…</div>
            <h2 id="nextTitle" style="margin:6px 0 0 0">—</h2>
            <p id="nextSummary" class="muted" style="margin-top:8px">Comfortable laying cushions available. Bring a blanket if desired.</p>
            <div style="margin-top:12px;display:flex;gap:10px">
              <a href="book.html" class="cta">Book your seat</a>
              <a href="#calendar" class="muted" style="align-self:center;text-decoration:underline">Full schedule</a>
            </div>
          </div>
        </div>

        <div class="card reveal" style="margin-top:14px">
          <h3 style="margin-top:0">Calendar</h3>
          <div id="calendar" class="event-list" aria-live="polite">
            <!-- events injected by JS -->
          </div>
        </div>

        <div class="card reveal" style="margin-top:14px">
          <h4 style="margin:0 0 8px 0">Important health notes</h4>
          <p class="muted" style="margin:0 0 6px 0">Sound gatherings are supportive for most people. They may not be appropriate for everyone. Contraindications include uncontrolled seizures/epilepsy, recent serious head trauma, early pregnancy (consult your provider), implanted medical devices sensitive to vibration, and acute psychosis. If you have concerns, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}} before attending.</p>
        </div>
      </div>

      <aside>
        <div class="card reveal">
          <h4 style="margin-top:0">Quick notes</h4>
          <p class="muted">Sessions run 60–120 minutes. Doors open 20 minutes prior. Sliding scale and limited concessions are available.</p>
          <hr style="border:none;border-top:1px solid #efe6de;margin:12px 0">
          <div style="display:flex;flex-direction:column;gap:8px">
            <strong>Location</strong>
            <div class="muted">{{CITY}}, {{STATE}}</div>
            <strong style="margin-top:6px">Contact</strong>
            <div class="muted"><a href="tel:{{PHONE}}">{{PHONE}}</a> — <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </div>

        <div class="card reveal" style="margin-top:14px">
          <h4 style="margin-top:0">What to bring</h4>
          <ul class="muted" style="margin:0 0 6px 18px">
            <li>Comfortable layers</li>
            <li>Blanket or mat</li>
            <li>Water bottle</li>
          </ul>
        </div>

      </aside>
    </section>

  </main>

  <footer>
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div class="muted">© <span id="year"></span> {{BUSINESS_NAME}} • <a href="privacy.html" class="muted">Privacy</a></div>
        <div class="muted">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </div>
  </footer>

  <!-- Modal: Try it now -->
  <div id="modal" class="modal-backdrop" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <header>
        <strong>Try a short practice</strong>
        <button id="closeModal" aria-label="Close">Close</button>
      </header>
      <div style="margin-top:8px">
        <div class="modes">
          <button data-mode="breath">Breathing</button>
          <button data-mode="journal">Journaling</button>
          <button data-mode="intention">Intention</button>
        </div>
        <div id="modeArea">
          <!-- interactive content injected here -->
        </div>
      </div>
    </div>
  </div>

  <script>
    // Basic data for events
    const EVENTS = [
      {id:1,title:"Evening Reset — Copper Sounds",date:"2026-03-05T18:30:00",duration:90,summary:"A focused 90-minute session using gongs and bowls.",price:"$30"},
      {id:2,title:"Lateral Calm — Midday Short",date:"2026-02-26T12:15:00",duration:45,summary:"A midday pause to reset attention.",price:"$18"},
      {id:3,title:"Deep Field Immersion",date:"2026-04-10T14:00:00",duration:180,summary:"Extended group immersion for deeper release.",price:"$85"},
      {id:4,title:"Community Sound & Breath",date:"2026-02-28T19:00:00",duration:60,summary:"A weekly communal session with guided breathwork.",price:"$20"}
    ];

    // Insert events, sort by date
    (function renderCalendar(){
      const list = document.getElementById('calendar');
      const now = new Date();
      const upcoming = EVENTS.map(e=>({...e,ts:new Date(e.date)})).filter(e=>e.ts>=now).sort((a,b)=>a.ts-b.ts);
      if(upcoming.length===0){ list.innerHTML = '<div class="muted">No upcoming events scheduled.</div>'; return; }
      list.innerHTML = upcoming.map(e=>{
        return `<div class=\"event\"><div class=\"left\"><strong>${escapeHtml(e.title)}</strong><div class=\"muted\">${formatDate(e.ts)} • ${e.duration} min</div></div><div><div class=\"muted\">${e.price}</div><a class=\"cta\" href=\"book.html?event=${e.id}\">Reserve</a></div></div>`;
      }).join('');

      // Next event widget
      const next = upcoming[0];
      document.getElementById('nextDate').textContent = formatDate(next.ts) + ' — ' + timeOf(next.ts);
      document.getElementById('nextTitle').textContent = next.title;
      document.getElementById('nextSummary').textContent = next.summary;
    })();

    function formatDate(d){ return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}); }
    function timeOf(d){ return d.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}); }
    function escapeHtml(s){ return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

    // Set year
    document.getElementById('year').textContent = new Date().getFullYear();

    // Modal / Try it now interactive
    const modal = document.getElementById('modal');
    const modeArea = document.getElementById('modeArea');
    document.getElementById('tryBtn').addEventListener('click',()=>openModal('breath'));
    document.getElementById('closeModal').addEventListener('click',closeModal);
    modal.addEventListener('click',e=>{if(e.target===modal) closeModal();});

    function openModal(defaultMode){
      modal.style.display='flex';
      modal.setAttribute('aria-hidden','false');
      showMode(defaultMode);
    }
    function closeModal(){
      modal.style.display='none';
      modal.setAttribute('aria-hidden','true');
      stopBreath();
    }

    document.querySelectorAll('.modes button').forEach(btn=>btn.addEventListener('click',()=>showMode(btn.dataset.mode)));

    // Breathing exercise
    let breathTimer=null, breathPhase=0;
    function showMode(mode){
      stopBreath();
      if(mode==='breath'){
        modeArea.innerHTML = '<div style="text-align:center"><div id="breathDot" class="breath-dot" aria-hidden></div><div id="breathText" style="margin-top:10px;font-weight:700">Prepare...</div><div class="muted" style="margin-top:8px">Follow the circle: inhale — hold — exhale</div></div>';
        startBreath();
      } else if(mode==='journal'){
        modeArea.innerHTML = '<div><div class="muted">Prompt (5 minutes): Write freely for a short moment.</div><textarea id="journalField" rows="6" style="width:100%;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #eee"></textarea><div style="margin-top:8px"><button id="startJ" class="cta">Start 5-min timer</button><button id="saveJ" style="margin-left:8px" class="cta">Save</button></div><div id="jTimer" class="muted" style="margin-top:8px"></div></div>';
        document.getElementById('startJ').addEventListener('click',()=>startJournalTimer(300));
        document.getElementById('saveJ').addEventListener('click',()=>{ localStorage.setItem('lastJournal',document.getElementById('journalField').value); alert('Saved locally'); });
      } else if(mode==='intention'){
        modeArea.innerHTML = '<div><label class="muted">Set a short intention:</label><input id="intent" style="width:100%;padding:10px;border-radius:8px;border:1px solid #eee;margin-top:8px" placeholder="e.g. soften my shoulders" /><div style="margin-top:10px"><button id="saveIntent" class="cta">Save intention</button></div><div id="intentMsg" class="muted" style="margin-top:8px"></div></div>';
        const save = document.getElementById('saveIntent');
        save.addEventListener('click',()=>{ const v=document.getElementById('intent').value.trim(); if(v.length){ localStorage.setItem('intent',v); document.getElementById('intentMsg').textContent='Saved — it will appear when you return.'; } else { document.getElementById('intentMsg').textContent='Please enter a short intention.';} });
        const existing = localStorage.getItem('intent'); if(existing) document.getElementById('intent').value = existing;
      }
    }

    function startBreath(){
      const dot = document.getElementById('breathDot');
      const txt = document.getElementById('breathText');
      breathPhase = 0; // 0 inhale,1 hold,2 exhale
      const phases = [4000,2000,6000];
      const labels = ['Breathe in','Hold','Exhale'];
      txt.textContent = labels[0];
      breathTimer = setInterval(()=>{
        breathPhase = (breathPhase+1)%3;
        txt.textContent = labels[breathPhase];
        const scale = breathPhase===0?1.0:breathPhase===1?1.25:0.6;
        dot.animate([{transform:`scale(${dot._lastScale||1})`},{transform:`scale(${scale})`}],{duration:600,easing:'ease-in-out',fill:'forwards'});
        dot._lastScale = scale;
      },6000);
    }
    function stopBreath(){ if(breathTimer){ clearInterval(breathTimer); breathTimer=null; } }

    function startJournalTimer(seconds){
      const el = document.getElementById('jTimer');
      let s = seconds;
      el.textContent = formatTimer(s);
      const t = setInterval(()=>{
        s--; if(s<=0){ clearInterval(t); el.textContent='Time!'; alert('5 minutes finished.'); } else el.textContent = formatTimer(s); },1000);
    }
    function formatTimer(s){ return Math.floor(s/60)+':' + String(s%60).padStart(2,'0'); }

    // Scroll reveal using IntersectionObserver with reduced-motion support
    (function revealSetup(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduced){ document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();

  </script>
</body>
</html>"} 
{"path":"private-sessions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#efe6dd;--accent:#6b402e;--muted:#7b6b62;--card:#fff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#2b231f}
    .wrap{max-width:920px;margin:0 auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
    .brand{font-weight:800;color:var(--accent)}
    nav a{margin-left:14px;text-decoration:none;color:var(--muted);font-weight:600}
    .intro{background:linear-gradient(180deg,#fff,#fff9);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.04)}
    .cols{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .card{background:var(--card);padding:16px;border-radius:10px}
    h1{margin:0 0 8px 0}
    .muted{color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;text-decoration:none;font-weight:700}
    .service{border-left:3px solid #eee;padding-left:12px;margin-bottom:10px}

    .reveal{opacity:0;transform:translateY(10px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (max-width:900px){.cols{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Gather</a>
        <a href="events.html">Calendar</a>
        <a href="private-sessions.html">Sessions</a>
        <a href="pricing.html">Invest</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <section class="intro reveal" id="top">
      <h1>Private resonance sessions</h1>
      <p class="muted">Bespoke one-on-one experiences for rest and recalibration. Options range from concise bespoke sessions to a dedicated VIP Day for deeper re-patterning.</p>
      <div style="margin-top:12px">
        <a class="cta" href="book.html">Request a private session</a>
        <button id="tryBtnPS" style="margin-left:8px" class="cta">Try it now</button>
      </div>
    </section>

    <div class="cols">
      <main>
        <div class="card reveal">
          <h3 style="margin-top:0">Formats</h3>
          <div class="service">
            <strong>Express Session — 45 minutes</strong>
            <div class="muted">A practical reset for body and breath. Useful before travel or a busy evening.</div>
          </div>
          <div class="service">
            <strong>Focused Session — 90 minutes</strong>
            <div class="muted">A complete private session with intention-setting, guided sound, and a short integration.</div>
          </div>
          <div class="service">
            <strong>VIP Day — Reserved Half Day</strong>
            <div class="muted">A VIP-style multi-hour immersion combining assessment, tailored instruments, and coaching. Ideal for aligned rest and a durable reset.</div>
          </div>

          <h4 style="margin-top:12px">How a private session flows</h4>
          <ol class="muted">
            <li>Quick intake and needs check</li>
            <li>Intention-setting and working frame</li>
            <li>Sound application — tuned bowls, bell work, and subtle percussion</li>
            <li>Quiet integration; short reflection and aftercare notes</li>
          </ol>
        </div>

        <div class="card reveal" style="margin-top:12px">
          <h4 style="margin-top:0">Contraindications & accessibility</h4>
          <p class="muted">Private sessions are adjusted when necessary. However, for safety: please disclose pregnancy (especially first trimester), implanted medical devices, recent traumatic brain injury, or uncontrolled seizures. We will adapt or recommend alternatives if needed. If you rely on sensory assistance, tell us in advance so we can prepare the space.</p>
        </div>
      </main>

      <aside>
        <div class="card reveal">
          <h4 style="margin-top:0">Rates & booking</h4>
          <div class="muted">
            <strong>Express (45m)</strong> — starting $95<br>
            <strong>Focused (90m)</strong> — starting $170<br>
            <strong>VIP Day (4–6 hrs)</strong> — custom pricing (inquire)
          </div>
          <div style="margin-top:10px">
            <a class="cta" href="pricing.html">See detailed pricing</a>
          </div>
        </div>

        <div class="card reveal" style="margin-top:12px">
          <h4 style="margin-top:0">Before you arrive</h4>
          <ul class="muted" style="margin:0 0 0 18px">
            <li>Limit heavy meals 60 minutes prior</li>
            <li>Remove noisy jewelry</li>
            <li>Share any medical notes with your practitioner</li>
          </ul>
        </div>

        <div class="card reveal" style="margin-top:12px">
          <h4 style="margin-top:0">Contact</h4>
          <div class="muted">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a> to begin the request.</div>
        </div>
      </aside>
    </div>

    <div style="margin-top:18px" class="reveal">
      <small class="muted">Sessions typically take place in a quiet studio. Mobile options available for an additional travel fee. All packages include brief written aftercare notes.</small>
    </div>

  </div>

  <!-- Try it now modal re-used -->
  <div id="modalPS" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,0.45);align-items:center;justify-content:center;z-index:90">
    <div style="background:#fff;padding:20px;border-radius:12px;width:92%;max-width:680px">
      <header style="display:flex;justify-content:space-between;align-items:center"><strong>Quick practice</strong><button id="closePS">Close</button></header>
      <div id="areaPS" style="margin-top:12px">Loading…</div>
    </div>
  </div>

  <script>
    // Reveal observer (with reduced-motion support)
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){ document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); } });
      },{threshold:0.14});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    })();

    // Try it modal: lightweight breathing guide
    const modalPS = document.getElementById('modalPS');
    const areaPS = document.getElementById('areaPS');
    document.getElementById('tryBtnPS').addEventListener('click',()=>{ modalPS.style.display='flex'; startMiniBreath(); });
    document.getElementById('closePS').addEventListener('click',()=>{ modalPS.style.display='none'; stopMiniBreath(); });

    let miniInterval=null, miniPhase=0;
    function startMiniBreath(){
      areaPS.innerHTML = '<div style="text-align:center"><div id="dotPS" style="width:60px;height:60px;border-radius:50%;background:'+getComputedStyle(document.documentElement).getPropertyValue('--accent')+';margin:18px auto"></div><div id="txtPS" style="font-weight:700">Inhale</div></div>';
      const dot = document.getElementById('dotPS');
      const txt = document.getElementById('txtPS');
      const seq=['Inhale','Hold','Exhale'];
      miniPhase=0; txt.textContent = seq[0];
      miniInterval = setInterval(()=>{
        miniPhase = (miniPhase+1)%3; txt.textContent = seq[miniPhase];
        const s = miniPhase===0?1.05:miniPhase===1?1.3:0.65;
        dot.style.transform = 'scale('+s+')';
      },4500);
    }
    function stopMiniBreath(){ if(miniInterval){ clearInterval(miniInterval); miniInterval=null;} }

  </script>
</body>
</html>"} 
{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f2ec;--accent:#5a3b2e;--muted:#8a7a71;--card:#fff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#2b231f}
    .wrap{max-width:980px;margin:0 auto;padding:28px}
    header{display:flex;justify-content:space-between;align-items:center}
    .brand{font-weight:800;color:var(--accent)}
    nav a{margin-left:12px;text-decoration:none;color:var(--muted);font-weight:600}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}
    .card{background:var(--card);padding:16px;border-radius:12px}
    h1{margin:0}
    .plan{border-radius:10px;padding:14px;border:1px solid #efe6de}
    .price{font-weight:800;color:var(--accent);font-size:20px}
    .muted{color:var(--muted)}

    .reveal{opacity:0;transform:translateY(8px);transition:opacity .5s ease,transform .5s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (max-width:960px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
