    </footer>
  </div>

  <script>
    // Simple reveal with reduced-motion support
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(reduced){ document.querySelectorAll('.reveal').forEach(r=>r.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
    })();
  </script>
